// Code generated from the Windpay-renamed system contracts. DO NOT EDIT.
//
// Replaces the bytecode of StakeHub, StakeCredit and GovToken at a fork block so
// the chain answers to Windpay names instead of the inherited BNB ones:
//
//	getPooledBNB         -> getPooledWind
//	totalPooledBNB       -> totalPooledWind
//	minSelfDelegationBNB -> minSelfDelegationWind
//	govBNB               -> govWIND
//	... 125 names in total
//
// Verified before generating this file:
//
//	Storage layout is identical across all three - every variable in the same
//	slot, same offset, same type. Solidity assigns slots by declaration order,
//	not by name, and nothing was reordered. No delegator loses stake.
//
//	StakeCredit and GovToken rebuild byte-for-byte identical to what is deployed,
//	which proves the toolchain reproduces the original build exactly.
//
//	StakeHub does NOT reproduce: the deployed code is 21 bytes smaller than any
//	rebuild from the surviving source. The source that produced it was overwritten
//	on 5 Oct 2025 and cannot be recovered - its ABI, constants and strings all
//	match, so the difference is logic with no external footprint. Replacing it
//	discards that difference. This was accepted deliberately.
//
//	BREATHE_BLOCK_INTERVAL is pinned to 600 here, matching what the deployed
//	contract reports. A mainnet build must restore 1 days.

package systemcontracts

import (
	"math/big"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/vm"
	"github.com/ethereum/go-ethereum/log"
)

// govTokenRenameStorage rewrites the ERC20 name and symbol, which live in storage
// rather than in code. __ERC20_init wrote them once at genesis, so new bytecode
// alone would leave the token still reporting "govBNB".
//
// Read from chain 5552040 before writing this:
//	slot 54 _name   = "BSC Governance Token"
//	slot 55 _symbol = "govBNB"
//
// Short strings occupy one slot: bytes left-aligned, last byte holding 2*length.
func govTokenRenameStorage(blockNumber *big.Int, addr common.Address, statedb vm.StateDB) error {
	name := common.HexToHash("0x57696e6470617920476f7665726e616e636520546f6b656e0000000000000030")
	symbol := common.HexToHash("0x676f7657494e440000000000000000000000000000000000000000000000000e")

	statedb.SetState(addr, common.BigToHash(big.NewInt(54)), name)
	statedb.SetState(addr, common.BigToHash(big.NewInt(55)), symbol)

	log.Info("Windpay rename: GovToken name and symbol rewritten",
		"block", blockNumber, "name", "Windpay Governance Token", "symbol", "govWIND")
	return nil
}

var windpayRenameUpgrade = &Upgrade{
	UpgradeName: "windpayRename",
	Configs: []*UpgradeConfig{
		{
			ContractAddr: common.HexToAddress(StakeHubContract),
			CommitUrl:    "windpay-rename-stakehub",
			Code:         "",
		},
		{
			ContractAddr: common.HexToAddress(StakeCreditContract),
			CommitUrl:    "windpay-rename-stakecredit",
			Code:         "",
		},
		{
			ContractAddr: common.HexToAddress(GovTokenContract),
			CommitUrl:    "windpay-rename-govtoken",
			AfterUpgrade: govTokenRenameStorage,
			Code:         "",
		},
	},
}
